import { test, expect, afterAll } from "bun:test";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { ContextPruningTracker } from "./src/core/context-pruning/tracker.ts";
import { recoverablePrune } from "./src/core/context-pruning/recovery.ts";
import type { ToolRecord } from "./src/core/context-pruning/types.ts";

const root = mkdtempSync(join(tmpdir(), "aide-dedup-regression-"));
afterAll(() => rmSync(root, { recursive: true, force: true }));
const output = "結果 😀 example\n".repeat(300);
const args = { query: "example" };
function run(tracker: ContextPruningTracker, id: string, value = output, scope = "session") {
  return tracker.process(id, "code_search", args, value, recoverablePrune(root, scope, id, value));
}
function record(id: string, originalOutput: string, prunedOutput: string | null = null): ToolRecord {
  return { callId: id, toolName: "code_search", args, originalOutput, prunedOutput, timestamp: 0 };
}

test("final emitted output and UTF-8 accounting survive history reload", () => {
  const tracker = new ContextPruningTracker(root);
  const results = [run(tracker, "one"), run(tracker, "two"), run(tracker, "three")];
  expect(tracker.getHistory().map(r => r.prunedOutput)).toEqual([null, results[1].output, results[2].output]);
  for (const result of results.slice(1)) {
    expect(result.output).toContain("callId: one");
    expect(readFileSync(result.recoveryPath!, "utf8")).toBe(output);
    expect(result.bytesSaved).toBe(Buffer.byteLength(output) - Buffer.byteLength(result.output));
  }
  const stats = tracker.getStats();
  expect(stats).toEqual({ totalCalls: 3, prunedCalls: 2,
    totalBytesSaved: results.reduce((sum, r) => sum + r.bytesSaved, 0),
    estimatedContextBytes: results.reduce((sum, r) => sum + Buffer.byteLength(r.output), 0) });
  const reloaded = new ContextPruningTracker(root);
  reloaded.loadHistory(JSON.parse(JSON.stringify(tracker.getHistory())));
  expect(reloaded.getStats()).toEqual(stats);
  expect(run(reloaded, "four").output).toContain("callId: one");
});

test("evicting the full baseline emits a new full baseline", () => {
  const tracker = new ContextPruningTracker(root, 2);
  run(tracker, "evict-one");
  run(tracker, "evict-two");
  run(tracker, "evict-three");
  expect(run(tracker, "evict-four")).toEqual({ output, modified: false, bytesSaved: 0 });
  expect(run(tracker, "evict-five").output).toContain("callId: evict-four");
});

test("most recent matching full result wins, skipping shortened and different outputs", () => {
  const tracker = new ContextPruningTracker(root);
  tracker.loadHistory([record("older", output), record("newer", output), record("different", "other"), record("short", output, "pointer")]);
  expect(run(tracker, "latest").output).toContain("callId: newer");
  const onlyShortened = new ContextPruningTracker(root);
  onlyShortened.loadHistory([record("short", "original", output)]);
  expect(run(onlyShortened, "no-target").modified).toBe(false);
});

test("recovery rejection becomes the latest full baseline with no savings", () => {
  const tracker = new ContextPruningTracker(root);
  run(tracker, "reject-one");
  expect(run(tracker, "reject-two", output, "")).toEqual({ output, modified: false, bytesSaved: 0 });
  expect(tracker.getHistory()[1].prunedOutput).toBeNull();
  expect(tracker.getStats()).toEqual({ totalCalls: 2, prunedCalls: 0, totalBytesSaved: 0, estimatedContextBytes: 2 * Buffer.byteLength(output) });
  expect(run(tracker, "reject-three").output).toContain("callId: reject-two");
});

test("small outputs and failed original retention remain full in history", () => {
  const tracker = new ContextPruningTracker(root);
  run(tracker, "small-one", "😀");
  expect(run(tracker, "small-two", "😀").modified).toBe(false);
  const blocked = join(root, "blocked");
  writeFileSync(blocked, "file");
  tracker.process("failure-one", "code_search", args, output);
  const result = tracker.process("failure-two", "code_search", args, output, recoverablePrune(blocked, "session", "failure-two", output));
  expect(result).toEqual({ output, modified: false, bytesSaved: 0 });
  expect(tracker.getHistory().every(r => r.prunedOutput === null)).toBe(true);
  expect(tracker.getStats().totalBytesSaved).toBe(0);
});

test("safe identical calls dedup while differing inputs, outputs and mutations do not", () => {
  const tracker = new ContextPruningTracker(root);
  run(tracker, "safe-one");
  expect(run(tracker, "safe-two").modified).toBe(true);
  expect(tracker.process("args", "code_search", { query: "other" }, output).modified).toBe(false);
  expect(run(tracker, "output", output + "changed").modified).toBe(false);
  for (const tool of ["Bash", "Write", "Edit", "memory_add"]) {
    tracker.process(`${tool}-one`, tool, args, output);
    expect(tracker.process(`${tool}-two`, tool, args, output)).toEqual({ output, modified: false, bytesSaved: 0 });
  }
});
